$_MODULE['<{kbgoogleshopping}prestashop>instructions_8563a22fd75e5a53d317f989c68b23ac'] = '1. Go to';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_b6c8b93a52d1fa156e7be803518b8c9a'] = 'Google Cloud console';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_1adc81dec2c3916a71686b391ff18b89'] = '2. Sign in to your Google account.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_ad39c4231c28d54aeaa2ef09fc76f1ee'] = '3. In the top-left corner, click on the hamburger menu (three horizontal lines) to expand the sidebar.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_b6d546beddba93a85d2cdec6a440e1c9'] = '4. Click on \"API & Services\" to expand the submenu, then select \"Dashboard\".';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_1ed5a0159fda7a4edd896219b2914af2'] = '5. Click on the \"+ ENABLE APIS AND SERVICES\" button at the top center of the page.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_2aa771ae0c2278573be427a03491e97a'] = '6. In the API Library, search for \"Content API for Shopping\".';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_e90a2c8a498d19104406addde3646277'] = '7. Click on \"Content API for Shopping\" from the search results.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_5f414ef14074cffb93105db6de76a65e'] = '8. Click the \"Enable\" button to activate the API for your project.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_f727edb9944ea39e3f903108e574cac1'] = '9. Once enabled, go back to the API & Services dashboard.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_6a2a0bce3e38657315ecc13819e09e34'] = '10. Now, navigate to \"Credentials\" on the left sidebar.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_5f373dea2061bdd0ff65b4c9fce5852b'] = '11. Click on \"+ CREATE CREDENTIALS\" and select \"OAuth client ID\".';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_4102eb85b25219c987deb08c0f8e440f'] = '12. Select the Application type as \"Web application\".';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_b63b2f100457b437d1de5f671911d21d'] = '13. Now under \"Authorized redirect URIs\", click on the \"+ ADD URI\" button.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_44223539a1f2121bed13329b30d169f0'] = '14. Enter the below URL for redirection:';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_3697f2671e1235e9fbd0a87d7af80a79'] = '15. Click on the Create Button.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_a6f68a396caab095fa259e94ef3e4828'] = '16. Now, use the Client ID and Client Secret for module connection.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_88b707749310e19483df09aa89217706'] = '17. Next, to obtain your Merchant ID, go to the Google Merchant Center.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_d41c03db5f14f1dd1c1f73485e339d9e'] = '18. Sign in or create an account if you don\'t have one.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_1b382b367fda2ebb0edda00120c68e2a'] = '19. Once in the Merchant Center dashboard, click on \"Settings\" (gear icon) in the top right corner.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_39df184b1e98de121d326809915ab0fe'] = '20. Under \"Business information\", you will find your Merchant ID listed at the top of the page.';
$_MODULE['<{kbgoogleshopping}prestashop>instructions_c29134e1fc68ac7aa8e10b611ec9f014'] = '21. Copy the Merchant ID for use in module configuration.';
